<script setup lang="ts">import {ref} from 'vue';import PrivateUpload from '@/components/PrivateUpload.vue';import {ElMessage} from 'element-plus';const id=ref(''),uploader=ref<InstanceType<typeof PrivateUpload>>();async function download(){try{await uploader.value?.download(id.value)}catch(e){ElMessage.error(e instanceof Error?e.message:'下载失败')}}</script><template><section class="page"><p class="eyebrow">MES BASE · 私有文件</p><h1>个人文件</h1><p class="muted">文件只对本人及上传时的范围开放。业务附件需由所属领域提供资源授权规则。</p><div class="panel welcome"><PrivateUpload ref="uploader" resource="personal" @uploaded="value=>id=value"/><el-divider/><label>文件标识<el-input v-model="id" placeholder="粘贴本人的文件标识"/></label><el-button type="primary" :disabled="!id" style="margin-top:16px" @click="download">下载文件</el-button></div></section></template>